mapper.select:
SELECT cm.id, cm.name, cm.type, cm.amount, cm.use_condition AS useCondition, cm.status, cm.sender_id AS senderId, cm.send_time AS sendTime, cm.receiver_id AS receiverId, u.nickname AS receiverName, cm.verify_time AS verifyTime, cm.valid_time AS validTime, cm.description, cm.station_ids AS stationIds, cm.creator, cm.create_time AS createTime, cm.update_time AS updateTime FROM coupon_mgmt cm LEFT JOIN user_info u ON cm.receiver_id = u.id AND u.deleted = 0 WHERE cm.deleted = 0
AND cm.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND cm.type = #{reqVO.type}
AND cm.status = #{reqVO.status}
AND cm.amount = #{reqVO.amount}
AND cm.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND cm.valid_time BETWEEN #{reqVO.validTime[0]} AND #{reqVO.validTime[1]}
AND cm.verify_time BETWEEN #{reqVO.verifyTime[0]} AND #{reqVO.verifyTime[1]}
AND cm.send_time BETWEEN #{reqVO.sendTime[0]} AND #{reqVO.sendTime[1]}
AND cm.send_time BETWEEN DATE(#{reqVO.date}) AND DATE(DATE_ADD(#{reqVO.date}, INTERVAL 1 DAY))
ORDER BY cm.id DESC
